<template>
    <div class="layout-px-spacing dash_1">
<teleport to="#breadcrumb">
    <ul class="navbar-nav flex-row ms-auto">
        <li class="nav-item">
            <span v-html="refreshButton(getSummaries, loading)"></span>
        </li>
        <li class="nav-item more-dropdown">
            <div class="dropdown custom-dropdown-icon">
                <a href="javascript:;" class="nav-link dropdown-toggle" id="ddlSettings" data-bs-toggle="dropdown" aria-expanded="false">
                    <span>Settings</span>
                    <svg
                        xmlns="http://www.w3.org/2000/svg"
                        width="24"
                        height="24"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        stroke-width="2"
                        stroke-linecap="round"
                        stroke-linejoin="round"
                        class="feather feather-chevron-down"
                    >
                        <polyline points="6 9 12 15 18 9"></polyline>
                    </svg>
                </a>
                <ul class="dropdown-menu dropdown-menu-end" aria-labelledby="ddlSettings">
                    <li><a class="dropdown-item fw-bolder bg-success text-white" data-value="Settings" href="javascript:void(0);">Settings</a></li>
                    <li><a class="dropdown-item" data-value="Mail" href="javascript:void(0);" @click="adjustCards(1)">Small Cards</a></li>
                    <li><a class="dropdown-item" data-value="Print" href="javascript:void(0);"  @click="adjustCards(-1)">Large Cards</a></li>
                    <li><a class="dropdown-item" data-value="Print" href="javascript:void(0);"  @click="cardNumber = 3">Reset Cards</a></li>
                    <li v-if="userId == 8"><a class="dropdown-item" data-value="Master Piece" href="javascript:void(0);"><router-link to="master-piece">Master Piece</router-link></a></li>
                    <!-- <li><a class="dropdown-item" data-value="Share" href="javascript:void(0);">Share</a></li> -->
                </ul>
            </div>
        </li>
    </ul>
</teleport>
        <!-- dynamic card starts -->
  <div class="row layout-top-spacing">


      <!-- v-if="!card.permission || user_permissions.includes(card.permission)"  -->
 <div v-if="loading" v-html="cardShimmer()"></div>      
<template v-else v-for="card in cards" :key="card.id">
<div 
  :class="`col-xl-${12/cardNumber} col-lg-${12/cardNumber} col-md-${12/cardNumber} col-sm-12 mb-4`"
  v-if="!card.permission || user_permissions.includes(card.permission)" 
>
    <div class="card shadow-lg p-3 h-100 position-relative">
      <Router-link :to="card.path" class="text-decoration-none">
        <div class="mb-3">
          <h4 class="text-dark">{{ card.name }}</h4>
        </div>

        <div class="row">
          <div v-for="subcard in card.sub_cards" :key="subcard.id" class="col-6 mb-3">
            <Router-link :to="subcard.path">
              <div class="card shadow border-start-primary h-100 p-3 d-flex flex-column align-items-center justify-content-center" :class="`text-${subcard.color}`">
                <h6 :class="`text-${subcard.color}`">{{ subcard.name }}</h6>
                <h4 :class="`text-${subcard.color}`">
                  <v-f-number 
                    :start-val="0" 
                    :end-val="getCountValue(subcard.count_source)" 
                    :duration="3000"
                  />
                </h4>
              </div>
            </Router-link>
          </div>
        </div>
      </Router-link>
    </div>
  </div>

    <button style="display: none;"  data-bs-toggle="modal" data-bs-target="#shortage-grn" id="shortage">

    </button>
</template>



</div>
<!-- dynamic card ends -->

    </div>



</template>

<script setup>
    import '@/assets/sass/widgets/widgets.scss';
    import { onMounted,ref,inject,watch } from 'vue';
    import { useMeta } from '@/composables/use-meta';
    import { VFNumber } from 'vue-animation-counter';
    import '@/assets/sass/scrollspyNav.scss';
    import '@/assets/sass/components/custom-counter.scss';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    useMeta({ title: 'Dashboard' });
    import axios from 'axios';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });


     const loading = ref(false)
     const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
     const userId = JSON.parse(localStorage.getItem("user")).id
     const summary = ref('')
     const showError = inject('showError');  
     const cardShimmer = inject('cardShimmer')
     const refreshButton = inject('refreshButton')


    const fetchSummary = () => {
      axiosInstance.get('dashboard/summary')
        .then(response => {
          summary.value = response.data
        })
        .catch(error => {
          showError(error.message);
          console.error('Error fetching summary :', error);
        });
    };
    fetchSummary();


const cards = ref([])
function getCountValue(countSource) {
  if (!countSource || typeof countSource !== 'string') return 0;
  try {
    return Function('summary', `return ${countSource}`)(summary.value);
  } catch (e) {
    return 0;
  }
}

const getCards = async ()=>{
  loading.value = true
  try{
    const response = await axiosInstance.get('main-cards')
    cards.value = response.data
  }catch(error){
   console.log(error)
   showError(error.message)
  }finally{
    loading.value = false
  }
}



const summaries = ref([])
const getSummaries = async () => {
   loading.value = true
  try {
    const response = await axiosInstance.get('dashboard/summary')
    const data = response.data

    const flattenWithDefaults = (obj, prefix = '') => {
      return Object.keys(obj).flatMap(key => {
        const fullKey = prefix ? `${prefix}.${key}` : key
        if (typeof obj[key] === 'object' && obj[key] !== null) {
          return flattenWithDefaults(obj[key], fullKey)
        } else {
          return `summary?.${fullKey} ?? 0`
        }
      })
    }

    const keysList = flattenWithDefaults(data)
    summaries.value = keysList.map(k => ({ name: k }))
  } catch (error) {
    console.log(error)
    showError(error.message)
  }finally{
     loading.value = false
  }
}

const cardNumber = ref(parseInt(localStorage.getItem('cardNumber')) || 3)

watch(cardNumber, (val) => {
  localStorage.setItem('cardNumber', val)
})
const validColumns = [1, 2, 3, 4, 6]
const adjustCards = (val) => {
  const currentIndex = validColumns.indexOf(cardNumber.value)
  const newIndex = currentIndex + val

  if (newIndex < 0) {
    showError('Minimum adjustment reached')
  } else if (newIndex >= validColumns.length) {
    showError('Maximum adjustment reached')
  } else {
    cardNumber.value = validColumns[newIndex]
  }
}
       onMounted(() => {
        getCards()
        getSummaries()
    });


    
</script>

<style>
body{
    background-color:white!important;
}
.card {
  text-align: center;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.card:hover {
  transform: translateY(-5px);
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
  cursor:pointer;
}
</style>
